namespace ghidra.features.codecompare.decompile;

using docking;
using docking.action;

/**
 * This is a base class for actions in a {@link DecompilerCodeComparisonView}
 */
public abstract class AbstractMatchedTokensAction : DockingAction {
	protected static readonly string MENU_PARENT = "Apply From Other Function";
	protected static readonly string HELP_TOPIC = "FunctionComparison";

	protected DecompilerCodeComparisonView comparisonProvider;
	protected bool disableOnReadOnly;

	/**
	 * Constructor
	 * 
	 * @param actionName name of action
	 * @param owner owner of action
	 * @param comparisonProvider diff panel containing action
	 * @param disableOnReadOnly if true, action will be disabled for read-only programs
	 */
	public AbstractMatchedTokensAction(string actionName, string owner,
			DecompilerCodeComparisonView comparisonProvider, bool disableOnReadOnly) : base(actionName, owner)
    {
		this.comparisonProvider = comparisonProvider;
		this.disableOnReadOnly = disableOnReadOnly;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!(context is DualDecompilerActionContext compareContext)) {
			return;
		}

		dualDecompilerActionPerformed(compareContext);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DualDecompilerActionContext compareContext)) {
			return false;
		}

		if (disableOnReadOnly) {
			if (compareContext.isActiveProgramReadOnly()) {
				return false;  // program is read-only, don't enable action
			}
		}

		return isEnabledForDualDecompilerContext(compareContext);
	}

	/**
	 * Subclasses return true if they are enabled for the given context
	 * 
	 * @param context the context
	 * @return true if enabled
	 */
	protected abstract bool isEnabledForDualDecompilerContext(
			DualDecompilerActionContext context);

	/**
	 * Subclasses will perform their work in this method
	 * @param context the context
	 */
	protected abstract void dualDecompilerActionPerformed(DualDecompilerActionContext context);

}
